/** @module local_autobrowsertimezone/timezone */
define("local_autobrowsertimezone/timezone",["core/ajax","core/notification"],function(Ajax,Notification){const getBrowserTimezone=()=>{try{return"undefined"==typeof Intl||"function"!=typeof Intl.DateTimeFormat?"":String(Intl.DateTimeFormat().resolvedOptions().timeZone||"").trim()}catch(error){return""}},markAttempt=key=>{try{if("1"===window.sessionStorage.getItem(key))return!1;window.sessionStorage.setItem(key,"1")}catch(error){}return!0};return{init:config=>{const safeConfig=config||{},browserTimezone=getBrowserTimezone(),currentTimezone=String(safeConfig.currentTimezone||"99");if(!browserTimezone||browserTimezone===currentTimezone)return;const attemptKey=["local_autobrowsertimezone",currentTimezone,browserTimezone].join(":");if(!markAttempt(attemptKey))return;const request={methodname:"local_autobrowsertimezone_update_timezone",args:{timezone:browserTimezone}};Ajax.call([request])[0].then(result=>(result.changed&&safeConfig.reload&&window.location.reload(),result)).catch(Notification.exception)}}});
